def get_maxgold(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    # dp[i][j] will store the max gold collected starting from cell (i,j) to the right end
    dp = [[0]*n for _ in range(m)]

    # Start from the rightmost column and move leftwards
    for j in range(n-1, -1, -1):
        for i in range(m):
            # If we are in the last column, max gold is just the cell's gold
            if j == n-1:
                dp[i][j] = grid[i][j]
            else:
                # Possible moves: right, right-up, right-down
                right = dp[i][j+1]
                right_up = dp[i-1][j+1] if i > 0 else 0
                right_down = dp[i+1][j+1] if i < m-1 else 0
                dp[i][j] = grid[i][j] + max(right, right_up, right_down)

    # Since start is restricted to top-left cell only (0,0)
    return dp[0][0]

