def set_left_most_unset_bit(n: int) -> int:
    if n == 0:
        # For 0, the highest set bit is undefined, but current bit length is 0,
        # so no bits to set. According to definition, no change.
        return n

    bit_length = n.bit_length()

    # Iterate from the most significant bit down to the least significant bit
    for i in reversed(range(bit_length)):
        # Check if the bit at position i is unset
