def lps(s: str) -> str:
    n = len(s)
    # dp[i][j] will hold the length of the longest palindromic subsequence in s[i:j+1]
    dp = [[0] * n for _ in range(n)]

    # Every single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = 2 + (dp[i + 1][j - 1] if i + 1 <= j - 1 else 0)
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Reconstruct the shortest palindrome sequence from the dp table
    i, j = 0, n - 1
    left_part = []
    right_part = []

    while i <= j:
        if i == j:
            # Middle character for odd-length palindrome
            left_part.append(s[i])
            break
        if s[i] == s[j]:
            left_part.append(s[i])
            right_part.append(s[j])
            i += 1
            j -= 1
        else:
            # Move in the direction of the longer palindromic subsequence
            if dp[i + 1][j] >= dp[i][j - 1]:
                i += 1
            else:
                j -= 1

    return "".join(left_part + right_part[::-1])

